SELECT 'gongkao', '组成关系', 'kp-xingce-judgement-analogy-logical-composition', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "组成关系"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "A 是 B 的一部分。A 属于 B 这个整体的不可分割的零件。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“轮胎 : 汽车”、“树枝 : 树木”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、致命考点（组成 vs 种属）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "怎么区分？用“是”来造句！"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "轮胎是汽车吗？不是。所以这是【组成】。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "苹果是水果吗？是。所以这是【种属】。绝对不能混淆！"}]}]}$$ AS jsonb), NULL, '组成关系的核心考点与解题技巧。', category_node.id, CAST('["判断推理", "组成关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_judgement_analogy_logical_composition", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
